async function ai(payload,target,stateId){const e=$(target),s=$(stateId);e.classList.remove('empty');e.innerHTML='<span class="loading">AI 正在处理</span>';if(s)s.textContent='生成中';try{const r=await fetch('/api/ai',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...payload,context:JSON.stringify(brand())})});const d=await r.json();if(!r.ok)throw Error(d.error||'请求失败');e.textContent=d.text||'没有返回内容';if(s)s.textContent='已完成';addHistory(payload,d.text||'没有返回内容',target);state.decisions++;store.set(K+'decisions',state.decisions);metrics();return d.text}catch(x){e.textContent='生成失败：'+x.message;if(s)s.textContent='失败';toast('生成失败')}}
