let createImages=[];
async function fileToCreateImage(file){
 if(!file||!file.type.startsWith('image/'))throw Error('请选择图片文件');
 if(file.size>18*1024*1024)throw Error(`${file.name} 太大，请选择小于18MB的图片`);
 const url=URL.createObjectURL(file),img=new Image();
 try{
  await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});
  const max=1100,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');
  canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));
  const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);
  return {id:Date.now()+Math.random(),name:file.name,width:img.width,height:img.height,data:canvas.toDataURL('image/jpeg',.68)};
 }finally{URL.revokeObjectURL(url)}
}
