function metrics(){const inn=state.income.filter(x=>x.kind==='收入').reduce((s,x)=>s+x.amount,0),out=state.income.filter(x=>x.kind==='支出').reduce((s,x)=>s+x.amount,0);$('#mLibrary').textContent=state.library.length;$('#mPlans').textContent=state.plans.filter(x=>!x.done).length;$('#mIncome').textContent=money(inn-out);$('#mDecisions').textContent=state.decisions}$('#exportData').onclick=()=>{const blob=new Blob([JSON.stringify({version:'3.6',...state,brand:brand()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='xiao-ai-studio-3.6-data.json';a.click();URL.revokeObjectURL(a.href)};metrics();recent();renderIncome();


