function renderPrompts(){const box=$('#promptList');if(!box)return;const q=($('#promptSearch').value||'').toLowerCase(),cat=$('#promptCategory').value;const items=state.prompts.filter(p=>(!cat||p.category===cat)&&(`${p.name} ${p.category} ${p.text}`.toLowerCase().includes(q)));box.innerHTML=items.length?items.map(p=>`<article class="prompt-card"><div><span>${p.category}</span><b>${p.name}</b></div><p>${p.text.slice(0,160)}${p.text.length>160?'…':''}</p><div><button class="soft small" data-use-prompt="${p.id}">带入创作</button><button class="icon small" data-copy-prompt="${p.id}">复制</button><button class="danger small" data-delete-prompt="${p.id}">删除</button></div></article>`).join(''):'<div class="empty-state"><b>还没有 Prompt</b><small>保存常用写作要求后，可以一键带入内容工厂。</small></div>';$$('[data-use-prompt]').forEach(b=>b.onclick=()=>{const p=state.prompts.find(x=>x.id==b.dataset.usePrompt);go('create');$('#createExtra').value=p.text;saveDraft();toast('已带入内容工厂')});$$('[data-copy-prompt]').forEach(b=>b.onclick=async()=>{const p=state.prompts.find(x=>x.id==b.dataset.copyPrompt);await navigator.clipboard.writeText(p.text);toast('已复制')});$$('[data-delete-prompt]').forEach(b=>b.onclick=()=>{state.prompts=state.prompts.filter(x=>x.id!=b.dataset.deletePrompt);store.set(K+'prompts',state.prompts);renderPrompts();toast('已删除')})}
$('#addPrompt').onclick=()=>{const name=prompt('Prompt 名称','小红书真实攻略');if(!name)return;const category=prompt('分类：小红书 / TikTok / 餐厅 / 英语学习 / 英国生活 / 其他','小红书')||'其他';const text=prompt('请输入 Prompt 内容','请根据我的真实经历，生成自然、不夸张、适合收藏的小红书文案。不要编造价格、地址或数据。');if(!text)return;state.prompts.unshift({id:Date.now(),name,category,text,date:new Date().toLocaleString('zh-CN')});store.set(K+'prompts',state.prompts);renderPrompts();toast('Prompt 已保存')};
