// Xiao AI Studio 3.3: automatic AI history
const historyTaskNames={team:'AI 团队方案',command:'AI 决策',create:'内容创作',cover:'封面方案',analyse:'数据诊断',doctor:'账号体检',batch:'批量内容方案'};
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function historyInput(payload){const copy={...payload};delete copy.image;delete copy.context;return copy}
function historyTitle(payload){const raw=payload.goal||payload.topic||payload.material||payload.profile||payload.note||historyTaskNames[payload.task]||'AI 记录';return String(raw).replace(/\s+/g,' ').trim().slice(0,46)||historyTaskNames[payload.task]||'AI 记录'}
function addHistory(payload,result,target){const item={id:Date.now(),task:payload.task||'other',type:historyTaskNames[payload.task]||'AI 记录',title:historyTitle(payload),input:historyInput(payload),result:String(result||''),target:String(target||''),date:new Date().toLocaleString('zh-CN'),timestamp:Date.now()};state.history.unshift(item);state.history=state.history.slice(0,200);store.set(K+'history',state.history);}
function renderHistory(){const box=$('#historyList');if(!box)return;const q=($('#historySearch').value||'').toLowerCase();const cat=$('#historyType').value;const items=state.history.filter(h=>(!cat||h.task===cat)&&(`${h.title} ${h.type} ${h.result} ${JSON.stringify(h.input)}`.toLowerCase().includes(q)));box.innerHTML=items.length?items.map(h=>`<article class="history-card"><div class="history-meta"><span>${esc(h.type)}</span><small>${esc(h.date)}</small></div><h3>${esc(h.title)}</h3><p>${esc(h.result.slice(0,220))}${h.result.length>220?'…':''}</p><div class="history-actions"><button class="primary small" data-open-history="${h.id}">查看</button><button class="soft small" data-copy-history="${h.id}">复制结果</button><button class="soft small" data-continue-history="${h.id}">继续创作</button><button class="danger small" data-delete-history="${h.id}">删除</button></div></article>`).join(''):'<div class="empty-state"><b>还没有历史记录</b><small>AI 每次成功生成后，会自动保存在当前浏览器。</small></div>';
$$('[data-open-history]').forEach(b=>b.onclick=()=>openHistory(Number(b.dataset.openHistory)));
$$('[data-copy-history]').forEach(b=>b.onclick=async()=>{const h=state.history.find(x=>x.id==b.dataset.copyHistory);if(!h)return;await navigator.clipboard.writeText(h.result);toast('结果已复制')});
$$('[data-continue-history]').forEach(b=>b.onclick=()=>continueHistory(Number(b.dataset.continueHistory)));
$$('[data-delete-history]').forEach(b=>b.onclick=()=>{state.history=state.history.filter(x=>x.id!=b.dataset.deleteHistory);store.set(K+'history',state.history);renderHistory();toast('历史记录已删除')});}
function openHistory(id){const h=state.history.find(x=>x.id===id);if(!h)return;$('#historyDetailTitle').textContent=h.title;$('#historyDetailMeta').textContent=`${h.type} · ${h.date}`;$('#historyDetailInput').textContent=JSON.stringify(h.input,null,2);$('#historyDetailResult').textContent=h.result;$('#historyModal').classList.add('show')}
function closeHistory(){ $('#historyModal').classList.remove('show') }
function continueHistory(id){const h=state.history.find(x=>x.id===id);if(!h)return;const p=h.input||{};if(h.task==='create'){go('create');if(p.type)$('#createType').value=p.type;if(p.topic)$('#createTopic').value=p.topic;if(p.language)$('#createLang').value=p.language;if(p.tone)$('#createTone').value=p.tone;if(p.goal)$('#createGoal').value=p.goal;if(p.extra)$('#createExtra').value=p.extra;$('#createResult').textContent=h.result;$('#createResult').classList.remove('empty');saveDraft()}else{go('command');$('#commandGoal').value=`继续完善这份${h.type}：\n${h.result}`;$('#commandExtra').value='请保留有用内容，并给出更具体、可执行的下一步。'}toast('已恢复，可继续修改')}
$('#historySearch').oninput=renderHistory;$('#historyType').onchange=renderHistory;$('#clearHistory').onclick=()=>{if(confirm('确定清空全部 AI 历史记录？此操作无法撤销。')){state.history=[];store.set(K+'history',[]);renderHistory();toast('历史记录已清空')}};
$('#closeHistory').onclick=closeHistory;$('#historyModal').onclick=e=>{if(e.target.id==='historyModal')closeHistory()};
renderHistory();

// Xiao AI Studio 3.5: Multi-image Studio
let studioImages=[],activeStudioId=null,blurMode=false,dragStart=null;
const canvas=$('#studioCanvas'),ctx=canvas?.getContext('2d');
const activeStudio=()=>studioImages.find(x=>x.id===activeStudioId)||null;
function fileToStudioItem(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(Error('请选择图片文件'));const r=new FileReader();r.onerror=()=>reject(Error('读取失败'));r.onload=()=>{const img=new Image();img.onload=()=>resolve({id:Date.now()+Math.random(),name:file.name,data:r.result,img,width:img.width,height:img.height,brightness:100,contrast:100,saturation:100,blurRects:[]});img.onerror=()=>reject(Error('图片格式不支持'));img.src=r.result};r.readAsDataURL(file)})}
async function addStudioFiles(files){const room=20-studioImages.length,list=[...files].filter(f=>f.type.startsWith('image/')).slice(0,room);if(!list.length)return toast(room?'请选择图片文件':'最多只能添加 20 张');for(const f of list){try{studioImages.push(await fileToStudioItem(f))}catch(e){toast(`${f.name}：${e.message}`)}}if(!activeStudioId&&studioImages.length)activeStudioId=studioImages[0].id;renderStudioLibrary();loadActiveStudio();if(files.length>room)toast('最多保留前 20 张图片')}
function renderStudioLibrary(){const box=$('#studioThumbs');$('#studioCount').textContent=`${studioImages.length} / 20`;$('#clearStudioImages').hidden=!studioImages.length;$('#removeStudioImage').hidden=!activeStudio();if(!studioImages.length){box.innerHTML='<div class="empty-state"><b>还没有图片</b><small>添加后可点选编辑</small></div>';return}box.innerHTML=studioImages.map((im,i)=>`<button type="button" class="studio-thumb ${im.id===activeStudioId?'active':''}" data-studio-id="${im.id}"><img src="${im.data}" alt="图片 ${i+1}"><span>${i+1}</span><small title="${im.name}">${im.name}</small></button>`).join('');$$('[data-studio-id]').forEach(b=>b.onclick=()=>{saveActiveControls();activeStudioId=Number(b.dataset.studioId);renderStudioLibrary();loadActiveStudio()})}
function loadActiveStudio(){const im=activeStudio();if(!im){canvas.style.display='none';$('#canvasEmpty').style.display='block';$('#studioFileName').textContent='未选择图片';$('#studioImageMeta').textContent='从左侧图片库选择';return}$('#studioFileName').textContent=im.name;$('#studioImageMeta').textContent=`${im.width} × ${im.height}`;$('#imgBrightness').value=im.brightness;$('#imgContrast').value=im.contrast;$('#imgSaturation').value=im.saturation;const max=1600,scale=Math.min(1,max/im.width,max/im.height);canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);drawStudio();canvas.style.display='block';$('#canvasEmpty').style.display='none'}
function saveActiveControls(){const im=activeStudio();if(!im)return;im.brightness=+$('#imgBrightness').value;im.contrast=+$('#imgContrast').value;im.saturation=+$('#imgSaturation').value}
$('#studioFile').onchange=e=>{addStudioFiles(e.target.files);e.target.value=''};
const drop=$('.image-drop');['dragenter','dragover'].forEach(ev=>drop?.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(ev=>drop?.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('drag')}));drop?.addEventListener('drop',e=>addStudioFiles(e.dataTransfer.files));
function drawStudio(targetCanvas=canvas,item=activeStudio()){if(!item||!targetCanvas)return;const c=targetCanvas.getContext('2d');c.clearRect(0,0,targetCanvas.width,targetCanvas.height);c.filter=`brightness(${item.brightness}%) contrast(${item.contrast}%) saturate(${item.saturation}%)`;c.drawImage(item.img,0,0,targetCanvas.width,targetCanvas.height);c.filter='none';item.blurRects.forEach(r=>pixelateOn(c,targetCanvas,r))}
function pixelateOn(c,target,r){const x=Math.max(0,Math.min(r.x,r.x+r.w)),y=Math.max(0,Math.min(r.y,r.y+r.h)),w=Math.min(target.width-x,Math.abs(r.w)),h=Math.min(target.height-y,Math.abs(r.h));if(w<2||h<2)return;const size=14,sw=Math.max(1,Math.round(w/size)),sh=Math.max(1,Math.round(h/size));const off=document.createElement('canvas');off.width=sw;off.height=sh;const o=off.getContext('2d');o.imageSmoothingEnabled=false;o.drawImage(target,x,y,w,h,0,0,sw,sh);c.imageSmoothingEnabled=false;c.drawImage(off,0,0,sw,sh,x,y,w,h);c.imageSmoothingEnabled=true}
['imgBrightness','imgContrast','imgSaturation'].forEach(id=>$('#'+id).oninput=()=>{saveActiveControls();drawStudio()});
$('#resetImage').onclick=()=>{const im=activeStudio();if(!im)return toast('请先选择图片');im.brightness=im.contrast=im.saturation=100;im.blurRects=[];loadActiveStudio();toast('当前图片已重置')};
$('#toggleBlur').onclick=()=>{if(!activeStudio())return toast('请先选择图片');blurMode=!blurMode;$('#toggleBlur').textContent=blurMode?'关闭手动打码':'开启手动打码';toast(blurMode?'请在图片上拖动框选':'手动打码已关闭')};
function canvasPoint(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}}
canvas?.addEventListener('pointerdown',e=>{if(!blurMode||!activeStudio())return;dragStart=canvasPoint(e);canvas.setPointerCapture(e.pointerId)});canvas?.addEventListener('pointerup',e=>{const im=activeStudio();if(!dragStart||!im)return;const p=canvasPoint(e);im.blurRects.push({x:dragStart.x,y:dragStart.y,w:p.x-dragStart.x,h:p.y-dragStart.y});dragStart=null;drawStudio()});
function renderFullStudio(item){const max=2200,scale=Math.min(1,max/item.width,max/item.height),c=document.createElement('canvas');c.width=Math.round(item.width*scale);c.height=Math.round(item.height*scale);const adjusted={...item,blurRects:item.blurRects.map(r=>({x:r.x*c.width/canvas.width,y:r.y*c.height/canvas.height,w:r.w*c.width/canvas.width,h:r.h*c.height/canvas.height}))};drawStudio(c,adjusted);return c}
function downloadCanvas(c,name,quality=.85,delay=0){setTimeout(()=>c.toBlob(blob=>{if(!blob)return;const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1200)},'image/jpeg',quality),delay)}
$('#downloadImage').onclick=()=>{const im=activeStudio();if(!im)return toast('请先选择图片');saveActiveControls();downloadCanvas(renderFullStudio(im),`edited-${im.name.replace(/\.[^.]+$/,'')}.jpg`,+$('#imgQuality').value/100)};
$('#nineGrid').onclick=()=>{const im=activeStudio();if(!im)return toast('请先选择图片');saveActiveControls();const src=renderFullStudio(im);for(let row=0;row<3;row++)for(let col=0;col<3;col++){const c=document.createElement('canvas');c.width=Math.floor(src.width/3);c.height=Math.floor(src.height/3);c.getContext('2d').drawImage(src,col*c.width,row*c.height,c.width,c.height,0,0,c.width,c.height);downloadCanvas(c,`xiao-grid-${row*3+col+1}.jpg`,.92,(row*3+col)*180)}toast('正在生成 9 张图片')};
$('#removeStudioImage').onclick=()=>{const im=activeStudio();if(!im)return;studioImages=studioImages.filter(x=>x.id!==im.id);activeStudioId=studioImages[0]?.id||null;renderStudioLibrary();loadActiveStudio();toast('当前图片已删除')};
$('#clearStudioImages').onclick=()=>{if(!confirm('确定清空图片工作室里的全部图片？'))return;studioImages=[];activeStudioId=null;renderStudioLibrary();loadActiveStudio();toast('已清空')};
async function batchDownload(quality){if(!studioImages.length)return toast('请先添加图片');saveActiveControls();studioImages.forEach((im,i)=>downloadCanvas(renderFullStudio(im),`xiao-${String(i+1).padStart(2,'0')}-${im.name.replace(/\.[^.]+$/,'')}.jpg`,quality,i*260));toast(`正在导出 ${studioImages.length} 张图片`)}
$('#batchExport').onclick=()=>batchDownload(+$('#imgQuality').value/100);$('#batchCompress').onclick=()=>batchDownload(.68);
async function imageAI(mode){const im=activeStudio();if(!im)return toast('请先选择图片');const question=$('#imageQuestion').value.trim()||(mode==='ocr'?'提取图片中的全部可见文字，按原顺序整理；再检查姓名、地址、电话、邮箱、二维码、条形码等隐私信息，并给出打码建议。':'分析图片的构图、清晰度、配色、信息重点和是否适合小红书发布，给出具体修改建议。');$('#imageAiResult').textContent='AI 正在识别...';$('#imageAiResult').classList.remove('empty');await ai({task:'imageStudio',mode,question,image:im.data},'#imageAiResult',null)}
$('#imageOcr').onclick=()=>imageAI('ocr');$('#imageAnalyse').onclick=()=>imageAI('analyse');
$('#generateImage').onclick=async()=>{const prompt=$('#imagePrompt').value.trim();if(!prompt)return toast('请输入图片描述');const box=$('#generatedImage');box.textContent='AI 正在生成图片...';box.classList.remove('empty');try{const r=await fetch('/api/image-generate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({prompt})});const d=await r.json();if(!r.ok)throw Error(d.error||'生成失败');box.innerHTML=`<img src="${d.image}" alt="AI generated"><button class="soft full" id="saveGenerated">保存图片</button>`;$('#saveGenerated').onclick=()=>{const a=document.createElement('a');a.href=d.image;a.download='xiao-ai-generated.png';a.click()}}catch(e){box.textContent='生成失败：'+e.message}};
renderStudioLibrary();loadActiveStudio();

// Xiao AI Studio 3.4: AI Daily Assistant
function dailyKey(){return new Date().toISOString().slice(0,10)}
function ensureDaily(){const key=dailyKey();if(!state.daily||state.daily.date!==key){state.daily={date:key,tasks:[{id:1,text:'完成一条可发布内容',done:false},{id:2,text:'整理今天的图片素材',done:false},{id:3,text:'检查一个未完成草稿',done:false}]};store.set(K+'daily',state.daily)}return state.daily}
function renderDaily(){const d=ensureDaily(),box=$('#dailyTaskList');if(!box)return;$('#dailyDate').textContent=new Intl.DateTimeFormat('zh-CN',{dateStyle:'full'}).format(new Date());box.innerHTML=d.tasks.length?d.tasks.map(t=>`<label class="daily-task ${t.done?'done':''}"><input type="checkbox" data-daily-check="${t.id}" ${t.done?'checked':''}><span>${esc(t.text)}</span><button class="danger small" data-daily-delete="${t.id}">删除</button></label>`).join(''):'<div class="empty-state"><b>今天还没有任务</b><small>点击右上角添加。</small></div>';const done=d.tasks.filter(t=>t.done).length,p=d.tasks.length?Math.round(done/d.tasks.length*100):0;$('#dailyProgress').style.width=p+'%';$('#dailyProgressText').textContent=`${p}% 完成 · ${done}/${d.tasks.length}`;$$('[data-daily-check]').forEach(x=>x.onchange=()=>{const t=d.tasks.find(v=>v.id==x.dataset.dailyCheck);t.done=x.checked;store.set(K+'daily',d);renderDaily()});$$('[data-daily-delete]').forEach(x=>x.onclick=e=>{e.preventDefault();d.tasks=d.tasks.filter(v=>v.id!=x.dataset.dailyDelete);store.set(K+'daily',d);renderDaily()});renderDailySuggestion()}
function renderDailySuggestion(){const suggestions=[];const draft=store.get(K+'createDraft',null);if(draft?.createTopic?.trim())suggestions.push('你有一份未完成的内容草稿，今天可以先继续修改并完成。');const active=state.projects.filter(p=>p.status==='进行中');if(active.length)suggestions.push(`你有 ${active.length} 个进行中的项目，优先推进“${active[0].name}”。`);if(state.plans.some(p=>!p.done))suggestions.push(`内容日历里还有 ${state.plans.filter(p=>!p.done).length} 条待发布计划。`);suggestions.push('今天只完成一个核心目标，比同时开始很多任务更有效。','先整理真实照片和花费，再让 AI 写文案，可以减少错误。');$('#dailySuggestion').textContent=suggestions[Math.floor(Math.random()*suggestions.length)]}
$('#addDailyTask').onclick=()=>{const text=prompt('今天要完成什么？');if(!text)return;const d=ensureDaily();d.tasks.push({id:Date.now(),text,done:false});store.set(K+'daily',d);renderDaily()};$('#resetDaily').onclick=()=>{const d=ensureDaily();d.tasks.forEach(t=>t.done=false);store.set(K+'daily',d);renderDaily()};$('#refreshDailySuggestion').onclick=renderDailySuggestion;renderDaily();


// Xiao AI Studio 3.4: Local Video Studio
let videoObjectUrl='', videoFileData=null, previewTimer=null, exportingVideo=false;
const videoPreview=$('#videoPreview'), videoCanvas=$('#videoCanvas');
function formatVideoTime(seconds){seconds=Math.max(0,Number(seconds)||0);const m=Math.floor(seconds/60),s=Math.floor(seconds%60);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function updateTrimSummary(){if(!videoPreview)return;let start=Math.max(0,Number($('#trimStart').value)||0),end=Math.min(videoPreview.duration||0,Number($('#trimEnd').value)||0);if(end<start)end=start;$('#trimSummary').textContent=`${formatVideoTime(start)} — ${formatVideoTime(end)} · ${Math.max(0,end-start).toFixed(1)}秒`}
function loadVideoFile(file){if(!file)return;if(!file.type.startsWith('video/'))return toast('请选择视频文件');if(exportingVideo)return toast('请等待当前导出完成');videoFileData=file;if(videoObjectUrl)URL.revokeObjectURL(videoObjectUrl);videoObjectUrl=URL.createObjectURL(file);videoPreview.src=videoObjectUrl;videoPreview.style.display='block';$('#videoEmpty').style.display='none';$('#videoFileName').textContent=`${file.name} · ${(file.size/1024/1024).toFixed(1)} MB`;$('#videoStatus').textContent='正在读取视频信息…';videoPreview.onloadedmetadata=()=>{$('#trimStart').value='0';$('#trimEnd').value=videoPreview.duration.toFixed(1);$('#trimStart').max=$('#trimEnd').max=videoPreview.duration;videoPreview.playbackRate=Number($('#videoSpeed').value);updateTrimSummary();$('#videoStatus').textContent=`视频时长 ${formatVideoTime(videoPreview.duration)}，可以开始剪辑。`}}
$('#videoFile').onchange=e=>loadVideoFile(e.target.files[0]);
const videoDrop=$('.video-drop');['dragenter','dragover'].forEach(ev=>videoDrop?.addEventListener(ev,e=>{e.preventDefault();videoDrop.classList.add('drag')}));['dragleave','drop'].forEach(ev=>videoDrop?.addEventListener(ev,e=>{e.preventDefault();videoDrop.classList.remove('drag')}));videoDrop?.addEventListener('drop',e=>loadVideoFile(e.dataTransfer.files[0]));
['trimStart','trimEnd'].forEach(id=>$('#'+id).oninput=updateTrimSummary);
$('#videoSpeed').onchange=()=>{videoPreview.playbackRate=Number($('#videoSpeed').value)};
$('#setTrimStart').onclick=()=>{if(!videoFileData)return toast('请先上传视频');$('#trimStart').value=videoPreview.currentTime.toFixed(1);if(Number($('#trimEnd').value)<videoPreview.currentTime)$('#trimEnd').value=videoPreview.currentTime.toFixed(1);updateTrimSummary()};
$('#setTrimEnd').onclick=()=>{if(!videoFileData)return toast('请先上传视频');$('#trimEnd').value=videoPreview.currentTime.toFixed(1);if(Number($('#trimStart').value)>videoPreview.currentTime)$('#trimStart').value=videoPreview.currentTime.toFixed(1);updateTrimSummary()};
$('#previewTrim').onclick=async()=>{if(!videoFileData)return toast('请先上传视频');clearInterval(previewTimer);const start=Number($('#trimStart').value),end=Number($('#trimEnd').value);if(end<=start)return toast('结束时间必须晚于开始时间');videoPreview.currentTime=start;videoPreview.playbackRate=Number($('#videoSpeed').value);await videoPreview.play();previewTimer=setInterval(()=>{if(videoPreview.currentTime>=end){videoPreview.pause();clearInterval(previewTimer)}},80)};
$('#resetVideo').onclick=()=>{if(!videoFileData)return;clearInterval(previewTimer);videoPreview.pause();videoPreview.currentTime=0;$('#trimStart').value=0;$('#trimEnd').value=videoPreview.duration.toFixed(1);$('#videoRatio').value='source';$('#videoSpeed').value='1';$('#videoMute').checked=false;videoPreview.playbackRate=1;$('#videoProgress').style.width='0%';updateTrimSummary();toast('视频设置已重置')};
function videoOutputSize(){const ratio=$('#videoRatio').value,w=videoPreview.videoWidth,h=videoPreview.videoHeight,max=1080;if(ratio==='source'){const scale=Math.min(1,max/Math.max(w,h));return [Math.round(w*scale),Math.round(h*scale)]}if(ratio==='9:16')return [720,1280];if(ratio==='1:1')return [1080,1080];return [1280,720]}
function drawVideoFrame(context,w,h){const sw=videoPreview.videoWidth,sh=videoPreview.videoHeight,target=w/h,source=sw/sh;let sx=0,sy=0,cw=sw,ch=sh;if(source>target){cw=sh*target;sx=(sw-cw)/2}else if(source<target){ch=sw/target;sy=(sh-ch)/2}context.drawImage(videoPreview,sx,sy,cw,ch,0,0,w,h)}
$('#captureCover').onclick=()=>{if(!videoFileData||!videoPreview.videoWidth)return toast('请先上传视频');const [w,h]=videoOutputSize(),c=document.createElement('canvas');c.width=w;c.height=h;drawVideoFrame(c.getContext('2d'),w,h);c.toBlob(blob=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='xiao-video-cover.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)},'image/png')};
$('#exportVideo').onclick=async()=>{if(!videoFileData)return toast('请先上传视频');if(exportingVideo)return toast('视频正在导出');if(!window.MediaRecorder||!videoCanvas.captureStream)return toast('当前浏览器不支持本地视频导出，请使用最新版 Chrome 或 Edge');const start=Number($('#trimStart').value),end=Number($('#trimEnd').value),speed=Number($('#videoSpeed').value);if(!(end>start))return toast('请选择有效的剪辑时间');const [w,h]=videoOutputSize(),context=videoCanvas.getContext('2d');videoCanvas.width=w;videoCanvas.height=h;exportingVideo=true;$('#exportVideo').disabled=true;$('#videoStatus').textContent='正在准备导出，请不要关闭页面…';$('#videoProgress').style.width='0%';videoPreview.pause();videoPreview.currentTime=start;await new Promise(resolve=>videoPreview.addEventListener('seeked',resolve,{once:true}));videoPreview.playbackRate=speed;
let stream=videoCanvas.captureStream(30),audioContext=null;if(!$('#videoMute').checked){try{audioContext=new (window.AudioContext||window.webkitAudioContext)();const source=audioContext.createMediaElementSource(videoPreview),dest=audioContext.createMediaStreamDestination();source.connect(dest);source.connect(audioContext.destination);dest.stream.getAudioTracks().forEach(t=>stream.addTrack(t))}catch(e){console.warn('Audio export unavailable',e)}}
const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(x=>MediaRecorder.isTypeSupported(x))||'';const recorder=new MediaRecorder(stream,mime?{mimeType:mime,videoBitsPerSecond:5000000}:undefined),chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{const blob=new Blob(chunks,{type:recorder.mimeType||'video/webm'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='xiao-video-edit.webm';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);exportingVideo=false;$('#exportVideo').disabled=false;$('#videoProgress').style.width='100%';$('#videoStatus').textContent='导出完成，视频已开始下载。';audioContext?.close();toast('视频导出完成')};recorder.start(500);await videoPreview.play();let raf=0;const render=()=>{drawVideoFrame(context,w,h);const progress=Math.min(1,(videoPreview.currentTime-start)/(end-start));$('#videoProgress').style.width=(progress*100).toFixed(1)+'%';$('#videoStatus').textContent=`正在导出 ${Math.round(progress*100)}%`;if(videoPreview.currentTime>=end||videoPreview.ended){videoPreview.pause();cancelAnimationFrame(raf);if(recorder.state!=='inactive')recorder.stop();return}raf=requestAnimationFrame(render)};render()};


// Xiao AI Studio 3.6: AI Voice Studio
let voiceObjectUrl='';
const voiceStyleInstructions={natural:'使用自然、真实、生活化的中文口语表达，停顿顺畅，不要像广告播音。',warm:'语气温柔亲切，像朋友分享，节奏舒缓，情绪自然。',story:'用适合睡前故事的叙述方式，声音柔和，有画面感，关键处稍作停顿。',lively:'语气轻快活泼，适合小红书和 TikTok 分享，但不要夸张喊叫。',calm:'语气沉稳清晰，适合攻略和知识讲解，重点信息适当强调。'};
function updateVoiceCount(){const el=$('#voiceText');if(el)$('#voiceCount').textContent=`${el.value.length} / 4096`}
$('#voiceText')?.addEventListener('input',updateVoiceCount);
$('#clearVoiceText')?.addEventListener('click',()=>{$('#voiceText').value='';updateVoiceCount();$('#voiceText').focus()});
$('#generateVoice')?.addEventListener('click',async()=>{const text=$('#voiceText').value.trim();if(!text)return toast('请先输入配音文字');if(text.length>4096)return toast('配音文字不能超过 4096 个字符');const btn=$('#generateVoice'),box=$('#voiceResult');btn.disabled=true;btn.textContent='正在生成…';box.className='voice-result';box.innerHTML='<div class="voice-loading">AI 正在生成配音</div>';try{const r=await fetch('/api/speech',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text,voice:$('#voiceName').value,speed:Number($('#voiceSpeed').value),style:voiceStyleInstructions[$('#voiceStyle').value]})});if(!r.ok){let message='配音生成失败';try{const d=await r.json();message=d.error||message}catch{}throw Error(message)}const blob=await r.blob();if(voiceObjectUrl)URL.revokeObjectURL(voiceObjectUrl);voiceObjectUrl=URL.createObjectURL(blob);box.innerHTML=`<audio controls playsinline src="${voiceObjectUrl}"></audio><div class="voice-download"><button class="primary full" id="downloadVoice">下载 MP3</button></div>`;$('#downloadVoice').onclick=()=>{const a=document.createElement('a');a.href=voiceObjectUrl;a.download=`xiao-ai-voice-${Date.now()}.mp3`;a.click()};toast('配音生成完成')}catch(e){box.className='voice-result empty';box.textContent='生成失败：'+e.message}finally{btn.disabled=false;btn.textContent='生成配音'}});
updateVoiceCount();


// 3.6.2 Script to Visual
let svScenes=[];
function svEscape(s=''){return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]||c))}
function svRender(){const box=$('#svScenes');$('#svClear').hidden=!svScenes.length;if(!svScenes.length){box.innerHTML='<div class="empty-state"><b>还没有分镜</b><small>粘贴脚本后点击“AI 拆分镜头”</small></div>';return}box.innerHTML=svScenes.map((s,i)=>`<article class="sv-scene" data-scene="${i}"><div class="sv-scene-head"><span>镜头 ${i+1}</span><small>${svEscape(s.duration||'')}</small></div><b>${svEscape(s.title||`镜头 ${i+1}`)}</b><p>${svEscape(s.visual||'')}</p><label>画面提示词<textarea data-sv-prompt="${i}">${svEscape(s.prompt||s.visual||'')}</textarea></label><div class="sv-actions"><button class="soft" data-sv-image="${i}">生成图片</button><button class="primary" data-sv-video="${i}">生成视频</button></div><div class="sv-output empty" id="svOutput${i}">尚未生成画面</div></article>`).join('');$$('[data-sv-prompt]').forEach(t=>t.oninput=()=>svScenes[+t.dataset.svPrompt].prompt=t.value);$$('[data-sv-image]').forEach(b=>b.onclick=()=>svGenerateImage(+b.dataset.svImage));$$('[data-sv-video]').forEach(b=>b.onclick=()=>svGenerateVideo(+b.dataset.svVideo))}
$('#svSplit')?.addEventListener('click',async()=>{const script=$('#svScript').value.trim();if(!script)return toast('请先输入脚本');const btn=$('#svSplit');btn.disabled=true;btn.textContent='正在拆分…';$('#svState').textContent='AI 正在拆分镜头';try{const r=await fetch('/api/script-scenes',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({script,style:$('#svStyle').value,ratio:$('#svRatio').value,count:Number($('#svCount').value),character:$('#svCharacter').value.trim()})});const d=await r.json();if(!r.ok)throw Error(d.error||'拆分失败');svScenes=Array.isArray(d.scenes)?d.scenes:[];svRender();$('#svState').textContent=`已生成 ${svScenes.length} 个镜头`;toast('分镜生成完成')}catch(e){$('#svState').textContent='生成失败';toast(e.message)}finally{btn.disabled=false;btn.textContent='✨ AI 拆分镜头'}});
$('#svClear')?.addEventListener('click',()=>{svScenes=[];svRender();$('#svState').textContent='等待脚本'});
async function svGenerateImage(i){const scene=svScenes[i],box=$(`#svOutput${i}`);if(!scene)return;box.className='sv-output';box.innerHTML='<span class="loading">AI 正在生成图片</span>';try{const ratio=$('#svRatio').value;const r=await fetch('/api/image-generate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({prompt:`${scene.prompt}. 统一设定：${$('#svCharacter').value||'保持人物与环境一致'}。画面风格：${$('#svStyle').value}。构图比例：${ratio}`,ratio})});const d=await r.json();if(!r.ok)throw Error(d.error||'图片生成失败');scene.image=d.image;box.innerHTML=`<img src="${d.image}" alt="镜头图片"><div class="sv-downloads"><button class="soft" data-save-sv-image="${i}">下载图片</button></div>`;$(`[data-save-sv-image="${i}"]`).onclick=()=>{const a=document.createElement('a');a.href=d.image;a.download=`xiao-scene-${i+1}.png`;a.click()}}catch(e){box.className='sv-output empty';box.textContent='生成失败：'+e.message}}
async function svGenerateVideo(i){const scene=svScenes[i],box=$(`#svOutput${i}`);if(!scene)return;box.className='sv-output';box.innerHTML='<span class="loading">正在创建视频任务</span>';try{const r=await fetch('/api/video-generate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({prompt:`${scene.prompt}. 统一设定：${$('#svCharacter').value||'保持人物与环境一致'}。风格：${$('#svStyle').value}`,ratio:$('#svRatio').value,seconds:$('#svSeconds').value})});const d=await r.json();if(!r.ok)throw Error(d.error||'视频任务创建失败');scene.videoId=d.id;await svPollVideo(i,d.id)}catch(e){box.className='sv-output empty';box.textContent='生成失败：'+e.message}}
async function svPollVideo(i,id){const box=$(`#svOutput${i}`);for(let n=0;n<120;n++){await new Promise(r=>setTimeout(r,n?5000:1800));const r=await fetch(`/api/video-status?id=${encodeURIComponent(id)}`),d=await r.json();if(!r.ok)throw Error(d.error||'查询失败');box.innerHTML=`<div class="sv-video-progress"><b>视频生成中 ${Number(d.progress||0)}%</b><div><i style="width:${Number(d.progress||0)}%"></i></div><small>${svEscape(d.status||'queued')}</small></div>`;if(d.status==='completed'){const src=`/api/video-content?id=${encodeURIComponent(id)}`;box.innerHTML=`<video controls playsinline src="${src}"></video><div class="sv-downloads"><a class="soft sv-link" href="${src}" download="xiao-scene-${i+1}.mp4">下载视频</a></div>`;toast('视频生成完成');return}if(d.status==='failed')throw Error(d.error?.message||'视频生成失败')}throw Error('视频生成等待超时，请稍后重试')}


// 3.6.3 Script dubbing and subtitles
let svDubAudioUrl=null,svDubBlob=null,svSubtitleCues=[],svDubDuration=0,svDubVideoUrl=null;
function svSplitSubtitleText(text,maxLen=20){
 const clean=String(text||'').replace(/\s+/g,'').trim();if(!clean)return[];
 const parts=clean.split(/(?<=[。！？!?；;，,])/).filter(Boolean),out=[];
 for(const part of parts){let t=part;while(t.length>maxLen){let cut=maxLen;for(let i=Math.min(maxLen,t.length-1);i>=Math.max(6,maxLen-6);i--){if('，。！？；、,.!?;'.includes(t[i])){cut=i+1;break}}out.push(t.slice(0,cut));t=t.slice(cut)}if(t)out.push(t)}return out;
}
function svTime(v){const ms=Math.max(0,Math.round(v*1000)),h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000),s=Math.floor(ms%60000/1000),x=ms%1000;return`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')},${String(x).padStart(3,'0')}`}
function svBuildCues(text,duration){const segs=svSplitSubtitleText(text,Number($('#svSubtitleLength').value)||20);const weights=segs.map(x=>Math.max(1,x.replace(/[，。！？；、,.!?;]/g,'').length)),total=weights.reduce((a,b)=>a+b,0)||1;let at=0;return segs.map((text,i)=>{const d=i===segs.length-1?duration-at:duration*weights[i]/total,start=at,end=Math.min(duration,at+d);at=end;return{text,start,end}})}
function svSrt(cues){return cues.map((c,i)=>`${i+1}\n${svTime(c.start)} --> ${svTime(c.end)}\n${c.text}\n`).join('\n')}
function svDownloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function svCurrentCue(t){return svSubtitleCues.find(c=>t>=c.start&&t<c.end)?.text||''}
function svRenderDubResult(){const box=$('#svDubResult');box.className='sv-dub-result';box.innerHTML=`<audio id="svDubAudio" controls playsinline src="${svDubAudioUrl}"></audio><div class="sv-dub-actions"><button class="soft" id="svDownloadMp3">下载 MP3</button><button class="soft" id="svDownloadSrt">下载 SRT 字幕</button></div><div id="svSubtitlePreview" class="sv-sub-preview ${$('#svSubtitleStyle').value}"><span>播放配音即可预览字幕</span></div>`;const audio=$('#svDubAudio'),preview=$('#svSubtitlePreview');audio.ontimeupdate=()=>{preview.innerHTML=`<span>${svEscape(svCurrentCue(audio.currentTime)||'')}</span>`};$('#svDownloadMp3').onclick=()=>svDownloadBlob(svDubBlob,`xiao-dubbing-${Date.now()}.mp3`);$('#svDownloadSrt').onclick=()=>svDownloadBlob(new Blob([svSrt(svSubtitleCues)],{type:'text/plain;charset=utf-8'}),`xiao-subtitles-${Date.now()}.srt`);$('#svCompose').disabled=!$('#svDubVideo').files?.[0]}
$('#svDub')?.addEventListener('click',async()=>{const text=$('#svScript').value.trim();if(!text)return toast('请先在上方输入脚本');if(text.length>4096)return toast('脚本超过 4096 字，请分段生成');const btn=$('#svDub'),box=$('#svDubResult');btn.disabled=true;btn.textContent='正在生成…';box.className='sv-dub-result';box.innerHTML='<div class="voice-loading">AI 正在生成配音和字幕</div>';try{const r=await fetch('/api/speech',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text,voice:$('#svVoice').value,speed:Number($('#svVoiceSpeed').value),style:'使用自然清晰、适合短视频旁白的中文表达，停顿自然。'})});if(!r.ok){let d={};try{d=await r.json()}catch{}throw Error(d.error||'配音生成失败')}svDubBlob=await r.blob();if(svDubAudioUrl)URL.revokeObjectURL(svDubAudioUrl);svDubAudioUrl=URL.createObjectURL(svDubBlob);const a=new Audio(svDubAudioUrl);await new Promise((ok,fail)=>{a.onloadedmetadata=ok;a.onerror=()=>fail(Error('无法读取配音时长'))});svDubDuration=a.duration;svSubtitleCues=svBuildCues(text,svDubDuration);svRenderDubResult();toast('配音和字幕生成完成')}catch(e){box.className='sv-dub-result empty';box.textContent='生成失败：'+e.message}finally{btn.disabled=false;btn.textContent='生成配音和字幕'}});
$('#svSubtitleStyle')?.addEventListener('change',()=>{const p=$('#svSubtitlePreview');if(p)p.className=`sv-sub-preview ${$('#svSubtitleStyle').value}`});
$('#svDubVideo')?.addEventListener('change',e=>{$('#svCompose').disabled=!(e.target.files?.[0]&&svDubBlob);if(svDubVideoUrl)URL.revokeObjectURL(svDubVideoUrl);svDubVideoUrl=e.target.files?.[0]?URL.createObjectURL(e.target.files[0]):null});
$('#svCompose')?.addEventListener('click',async()=>{const file=$('#svDubVideo').files?.[0];if(!file||!svDubBlob)return toast('请先生成配音，并选择一个视频');const btn=$('#svCompose'),box=$('#svDubResult');btn.disabled=true;btn.textContent='正在合成…';try{const video=document.createElement('video'),audio=document.createElement('audio');video.src=svDubVideoUrl;audio.src=svDubAudioUrl;video.muted=true;video.playsInline=true;await Promise.all([new Promise((ok,fail)=>{video.onloadedmetadata=ok;video.onerror=fail}),new Promise((ok,fail)=>{audio.onloadedmetadata=ok;audio.onerror=fail})]);const ratio=$('#svRatio').value,[rw,rh]=ratio==='16:9'?[1280,720]:ratio==='1:1'?[900,900]:[720,1280],canvas=document.createElement('canvas');canvas.width=rw;canvas.height=rh;const c=canvas.getContext('2d'),stream=canvas.captureStream(30),ac=new AudioContext(),src=ac.createMediaElementSource(audio),dest=ac.createMediaStreamDestination();src.connect(dest);src.connect(ac.destination);dest.stream.getAudioTracks().forEach(t=>stream.addTrack(t));const types=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/mp4'];const mime=types.find(x=>MediaRecorder.isTypeSupported(x))||'';const rec=new MediaRecorder(stream,mime?{mimeType:mime}:undefined),chunks=[];rec.ondataavailable=e=>e.data.size&&chunks.push(e.data);const done=new Promise(ok=>rec.onstop=ok);rec.start(1000);await ac.resume();video.currentTime=0;audio.currentTime=0;await Promise.all([video.play(),audio.play()]);const total=Math.min(video.duration||svDubDuration,svDubDuration),style=$('#svSubtitleStyle').value;await new Promise(ok=>{function draw(){const t=audio.currentTime,scale=Math.max(rw/video.videoWidth,rh/video.videoHeight),dw=video.videoWidth*scale,dh=video.videoHeight*scale;c.clearRect(0,0,rw,rh);c.drawImage(video,(rw-dw)/2,(rh-dh)/2,dw,dh);const text=svCurrentCue(t);if(text){const size=Math.max(30,Math.round(rw*.052));c.font=`700 ${size}px sans-serif`;c.textAlign='center';c.textBaseline='middle';const y=rh*.84,metrics=c.measureText(text),pad=18;if(style==='box'){c.fillStyle='rgba(0,0,0,.58)';c.fillRect((rw-metrics.width)/2-pad,y-size*.75,metrics.width+pad*2,size*1.5)}c.lineWidth=Math.max(5,size*.12);c.strokeStyle='rgba(0,0,0,.9)';c.strokeText(text,rw/2,y);c.fillStyle=style==='yellow'?'#ffd84a':'#fff';c.fillText(text,rw/2,y)}box.innerHTML=`<div class="compose-progress"><b>正在合成 ${Math.min(100,Math.round(t/total*100))}%</b><div><i style="width:${Math.min(100,t/total*100)}%"></i></div></div>`;if(t>=total||audio.ended){ok();return}requestAnimationFrame(draw)}draw()});video.pause();audio.pause();rec.stop();await done;ac.close();const blob=new Blob(chunks,{type:mime||'video/webm'}),ext=(mime||'').includes('mp4')?'mp4':'webm';svDownloadBlob(blob,`xiao-dubbed-video-${Date.now()}.${ext}`);svRenderDubResult();toast('合成完成，视频已开始下载')}catch(e){svRenderDubResult();toast('合成失败：'+(e.message||e))}finally{btn.disabled=false;btn.textContent='合成带配音字幕的视频'}});
